function getSceneTemplateSlotId(item = {}, templateId = '', index = 0) {
  return (
    item.sceneTemplateSlotId ||
    `${item.sceneTemplateId || templateId || 'scene-template'}:slot-${index + 1}`
  );
}

function getEditorLinkedSelectionIds(activity = {}, objectId = '') {
  const objects = Array.isArray(activity?.objects) ? activity.objects : [];
  const current = objects.find((item) => item.id === objectId) || null;
  if (!current) return new Set(objectId ? [objectId] : []);

  const layerId = current.layerId || 'base';
  const linkedActionTargetId = String(current.linkedActionTargetId || '').trim();
  const linkedHoverGroup = String(current.linkedHoverGroup || '').trim();
  const selectionIds = new Set([current.id]);

  if (linkedActionTargetId) {
    objects.forEach((item) => {
      if ((item.layerId || 'base') !== layerId) return;
      if (
        item.id === linkedActionTargetId ||
        String(item.linkedActionTargetId || '').trim() === linkedActionTargetId
      ) {
        selectionIds.add(item.id);
      }
    });
  }

  if (linkedHoverGroup) {
    objects.forEach((item) => {
      if ((item.layerId || 'base') !== layerId) return;
      if (String(item.linkedHoverGroup || '').trim() === linkedHoverGroup) {
        selectionIds.add(item.id);
      }
    });
  }

  return selectionIds;
}

function getEditorPrimaryObjectId(activity = {}, objectId = '') {
  const objects = Array.isArray(activity?.objects) ? activity.objects : [];
  const current = objects.find((item) => item.id === objectId) || null;
  if (!current) return objectId || '';

  const linkedActionTargetId = String(current.linkedActionTargetId || '').trim();
  if (linkedActionTargetId && objects.some((item) => item.id === linkedActionTargetId)) {
    return linkedActionTargetId;
  }

  const linkedIds = [...getEditorLinkedSelectionIds(activity, objectId)];
  const labelCandidate = linkedIds
    .map((id) => objects.find((item) => item.id === id))
    .find((item) => item && String(item.sceneTemplateSlotId || '').endsWith('-label'));
  if (labelCandidate?.id) return labelCandidate.id;

  return current.id;
}

function getEditorGroupedObjectEntries(activity = {}, inputObjects = []) {
  const objects = Array.isArray(inputObjects) ? inputObjects : [];
  const seen = new Set();
  const entries = [];

  objects.forEach((item) => {
    if (!item) return;
    const ids = [...getEditorLinkedSelectionIds(activity, item.id)];
    const primaryId = getEditorPrimaryObjectId(activity, item.id) || item.id;
    if (seen.has(primaryId)) return;
    seen.add(primaryId);
    const primaryObject =
      objects.find((candidate) => candidate.id === primaryId) ||
      (Array.isArray(activity?.objects)
        ? activity.objects.find((candidate) => candidate.id === primaryId)
        : null) ||
      item;
    entries.push({
      primaryId,
      ids,
      object: primaryObject,
    });
  });

  return entries;
}

function isButtonIntroInteractiveSlot(item = {}) {
  const slotId = String(item.sceneTemplateSlotId || '');
  const label = String(item.label || '').trim();
  const normalizedLabel = label.toLocaleUpperCase('tr-TR');
  return (
    slotId.endsWith(':start-button') ||
    slotId.endsWith(':start-icon') ||
    slotId.endsWith(':close-button') ||
    normalizedLabel.includes('ETKİNLİĞİ BAŞLAT') ||
    ['×', 'X', '✕', '✖'].includes(label)
  );
}

function isLaunchIntroControl(item = {}) {
  const slotId = String(item.sceneTemplateSlotId || '');
  const label = String(item.label || '')
    .trim()
    .toLocaleUpperCase('tr-TR');
  return (
    slotId.endsWith(':intro-button') ||
    slotId.endsWith(':intro-icon') ||
    slotId.endsWith(':intro-icon-bg') ||
    slotId.endsWith(':intro-icon-text') ||
    label.includes('ETKİNLİK TANITIMI')
  );
}

function isLaunchStartControl(item = {}) {
  const slotId = String(item.sceneTemplateSlotId || '');
  const label = String(item.label || '')
    .trim()
    .toLocaleUpperCase('tr-TR');
  return (
    slotId.endsWith(':start-button') ||
    slotId.endsWith(':start-icon') ||
    slotId.endsWith(':start-icon-bg') ||
    slotId.endsWith(':start-icon-text') ||
    label.includes('ETKİNLİĞİ BAŞLAT')
  );
}

function isLaunchInteractiveSlot(item = {}) {
  return isLaunchIntroControl(item) || isLaunchStartControl(item);
}

function getSceneTemplateAutoTargets(slide = {}, options = {}) {
  const slides =
    Array.isArray(options.slides) && options.slides.length
      ? options.slides
      : Array.isArray(slide.slides)
        ? slide.slides
        : [];
  const currentSlideId = String(options.currentSlideId || slide.id || slide.currentSlideId || '');
  const isTemplateSlide = (item) =>
    [SCENE_TEMPLATE_LAUNCH_PAGE_ID, SCENE_TEMPLATE_BUTTON_INTRO_ID].includes(
      String(item?.sceneTemplateId || '')
    );
  const launchSlide =
    slides.find((item) => String(item?.sceneTemplateId || '') === SCENE_TEMPLATE_LAUNCH_PAGE_ID) ||
    null;
  const introSlide =
    slides.find((item) => String(item?.sceneTemplateId || '') === SCENE_TEMPLATE_BUTTON_INTRO_ID) ||
    null;
  const launchIndex = launchSlide ? slides.findIndex((item) => item.id === launchSlide.id) : -1;
  const questionSlideAfterLaunch =
    launchIndex >= 0 ? slides.slice(launchIndex + 1).find((item) => !isTemplateSlide(item)) : null;
  const questionSlide =
    questionSlideAfterLaunch ||
    slides.find((item) => item.id !== currentSlideId && !isTemplateSlide(item)) ||
    slides.find((item) => !isTemplateSlide(item)) ||
    null;

  return {
    launchSlideValue: launchSlide?.id || '__prev__',
    introSlideValue: introSlide?.id || '__next__',
    questionSlideValue:
      questionSlide?.id ||
      (String(slide.sceneTemplateId || '') === SCENE_TEMPLATE_BUTTON_INTRO_ID
        ? '__prev__'
        : '__next__'),
  };
}

function getSceneTemplateDefaultTriggerValue(
  templateId = '',
  trigger = {},
  targetObject = {},
  targets = {}
) {
  if (templateId === SCENE_TEMPLATE_BUTTON_INTRO_ID) {
    if (isButtonIntroInteractiveSlot(targetObject)) {
      return String(targetObject.sceneTemplateSlotId || '').endsWith(':close-button') ||
        ['×', 'X', '✕', '✖'].includes(String(targetObject.label || '').trim())
        ? targets.launchSlideValue
        : targets.questionSlideValue;
    }
    return trigger.value;
  }
  if (templateId === SCENE_TEMPLATE_LAUNCH_PAGE_ID) {
    if (isLaunchIntroControl(targetObject)) return targets.introSlideValue;
    if (isLaunchStartControl(targetObject)) return targets.questionSlideValue;
  }
  return trigger.value;
}

function applySceneTemplatePresetToUserObject(
  item = {},
  presetId = DEFAULT_ANSWER_LAYER_STYLE_PRESET_ID
) {
  const preset =
    getAnswerLayerStylePresetById(presetId) ||
    getAnswerLayerStylePresetById(DEFAULT_ANSWER_LAYER_STYLE_PRESET_ID);
  const style = item.style || {};
  if (item.type === 'button') {
    const shapeStyle = getPresetButtonShapeStyle(preset, 'accent');
    return {
      ...item,
      buttonMotion: { ...(preset?.motion || {}), ...(item.buttonMotion || {}) },
      style: {
        ...style,
        background: shapeStyle.background || preset?.accentGradient || style.background,
        borderColor: shapeStyle.borderColor || preset?.accentBorder || style.borderColor,
        borderWidth: shapeStyle.borderWidth ?? style.borderWidth ?? 2,
        borderRadius: shapeStyle.borderRadius ?? style.borderRadius ?? preset?.buttonRadius ?? 14,
        color: shapeStyle.color || preset?.accentText || style.color,
        boxShadow: shapeStyle.boxShadow || style.boxShadow,
        textShadow: shapeStyle.textShadow || style.textShadow,
      },
    };
  }
  if (item.type === 'text') {
    return {
      ...item,
      style: {
        ...style,
        background:
          style.background === 'transparent' || !style.background
            ? 'transparent'
            : preset?.surface || style.background,
        borderColor:
          style.borderColor === 'transparent' || !style.borderColor
            ? 'transparent'
            : preset?.surfaceBorder || style.borderColor,
        color: preset?.bodyColor || style.color,
        boxShadow:
          style.boxShadow === 'none' || !style.boxShadow
            ? 'none'
            : preset?.surfaceShadow || style.boxShadow,
      },
    };
  }
  if (item.type === 'shape' && !item.imageData) {
    return {
      ...item,
      style: {
        ...style,
        background: preset?.surfaceAlt || style.background,
        borderColor: preset?.surfaceBorder || style.borderColor,
        color: 'transparent',
        boxShadow: preset?.surfaceShadow || style.boxShadow,
      },
    };
  }
  return item;
}

function applySceneTemplateToSlide(slide = {}, options = {}) {
  const templateId = String(options.templateId || slide.sceneTemplateId || '').trim();
  const presetId = String(
    options.presetId ||
      slide.sceneTemplatePresetId ||
      slide.answerLayerStylePresetId ||
      DEFAULT_ANSWER_LAYER_STYLE_PRESET_ID
  );
  const preserveNonGenerated = options.preserveNonGenerated !== false;
  const replaceExisting = options.replaceExisting === true;
  const respectDeletedSlotsOption = options.respectDeletedSlots !== false;
  const currentObjects = Array.isArray(slide.objects) ? slide.objects : [];
  const nonTemplateObjects = currentObjects.filter((item) => !isGeneratedSceneTemplateObject(item));
  const currentGeneratedObjects = currentObjects
    .filter(
      (item) =>
        isGeneratedSceneTemplateObject(item) &&
        (!item.sceneTemplateId || item.sceneTemplateId === templateId)
    )
    .sort((a, b) => (Number(a.zIndex) || 0) - (Number(b.zIndex) || 0));
  const currentTriggers = Array.isArray(slide.triggers) ? slide.triggers : [];
  const nonTemplateTriggers = currentTriggers.filter(
    (item) => !isGeneratedSceneTemplateObject(item)
  );
  const rawManualClickTargets = new Set(
    nonTemplateTriggers
      .filter((trigger) => (trigger.when || 'onClick') === 'onClick')
      .map((trigger) => trigger.target)
      .filter(Boolean)
  );

  if (!templateId) {
    return {
      ...slide,
      sceneTemplateId: '',
      sceneTemplatePresetId: '',
      sceneTemplateVersion: 0,
      activeLayerId: 'base',
      selectedObjectId: null,
      objects: nonTemplateObjects,
      triggers: nonTemplateTriggers,
      timeline: syncTimelineWithObjects({ ...slide, objects: nonTemplateObjects }),
    };
  }

  if (templateId !== SCENE_TEMPLATE_BUTTON_INTRO_ID && templateId !== SCENE_TEMPLATE_LAUNCH_PAGE_ID)
    return slide;

  const templateResult =
    templateId === SCENE_TEMPLATE_LAUNCH_PAGE_ID
      ? buildLaunchPageSceneTemplate(slide, presetId)
      : buildButtonIntroSceneTemplateObjects(slide, presetId);
  const generatedObjects = (templateResult.objects || []).map((item, index) => ({
    ...item,
    sceneTemplateSlotId: getSceneTemplateSlotId(item, templateId, index),
  }));
  const isOutdatedSceneTemplate =
    Number(slide.sceneTemplateVersion || 0) < SCENE_TEMPLATE_VERSION ||
    currentGeneratedObjects.some(
      (item) => Number(item.sceneTemplateVersion || 0) < SCENE_TEMPLATE_VERSION
    );
  const respectDeletedSlots =
    respectDeletedSlotsOption &&
    !replaceExisting &&
    !isOutdatedSceneTemplate &&
    currentGeneratedObjects.some((item) => item.sceneTemplateSlotId);
  const currentBySlot = new Map(
    currentGeneratedObjects.map((item, index) => [
      getSceneTemplateSlotId(item, templateId, index),
      item,
    ])
  );
  if (templateId === SCENE_TEMPLATE_BUTTON_INTRO_ID) {
    const startSlotId = `${templateId}:start-button`;
    const closeSlotId = `${templateId}:close-button`;
    if (!currentBySlot.has(startSlotId)) {
      const currentStart = currentGeneratedObjects.find((item) =>
        String(item.label || '')
          .toLocaleUpperCase('tr-TR')
          .includes('ETKİNLİĞİ BAŞLAT')
      );
      if (currentStart) currentBySlot.set(startSlotId, currentStart);
    }
    if (!currentBySlot.has(closeSlotId)) {
      const currentClose = currentGeneratedObjects.find(
        (item) =>
          item.type === 'button' && ['×', 'X', '✕', '✖'].includes(String(item.label || '').trim())
      );
      if (currentClose) currentBySlot.set(closeSlotId, currentClose);
    }
  }
  if (templateId === SCENE_TEMPLATE_LAUNCH_PAGE_ID) {
    const startSlotId = `${templateId}:start-button`;
    const introSlotId = `${templateId}:intro-button`;
    if (!currentBySlot.has(startSlotId)) {
      const currentStart = currentGeneratedObjects.find((item) =>
        String(item.label || '')
          .toLocaleUpperCase('tr-TR')
          .includes('ETKİNLİĞİ BAŞLAT')
      );
      if (currentStart) currentBySlot.set(startSlotId, currentStart);
    }
    if (!currentBySlot.has(introSlotId)) {
      const currentIntro = currentGeneratedObjects.find((item) =>
        String(item.label || '')
          .toLocaleUpperCase('tr-TR')
          .includes('ETKİNLİK TANITIMI')
      );
      if (currentIntro) currentBySlot.set(introSlotId, currentIntro);
    }
  }
  const generatedIdMap = new Map();
  const nextGeneratedObjects = generatedObjects
    .filter(
      (item) =>
        !respectDeletedSlots ||
        currentBySlot.has(item.sceneTemplateSlotId) ||
        item.forceSceneTemplateLayout === true
    )
    .map((item) => {
      const current = currentBySlot.get(item.sceneTemplateSlotId);
      if (!current) {
        generatedIdMap.set(item.id, item.id);
        return item;
      }
      const preserveUserLayout =
        current.userEditedSceneTemplate === true && item.forceSceneTemplateLayout !== true;
      const shouldPreserveObjectAction =
        templateId !== SCENE_TEMPLATE_BUTTON_INTRO_ID ||
        isButtonIntroInteractiveSlot(item) ||
        isButtonIntroInteractiveSlot(current);
      const merged = {
        ...item,
        id: current.id,
        visible: current.visible,
        locked: current.locked ?? item.locked,
        ...(preserveUserLayout
          ? {
              x: current.x,
              y: current.y,
              width: current.width,
              height: current.height,
              rotation: current.rotation,
              label: current.label,
              text: current.text,
              content: current.content,
            }
          : {}),
        runtimeAction: rawManualClickTargets.has(current.id)
          ? ''
          : shouldPreserveObjectAction
            ? current.runtimeAction || item.runtimeAction
            : item.runtimeAction,
        variableBindings: current.variableBindings || item.variableBindings,
        sceneTemplateSlotId: item.sceneTemplateSlotId,
      };
      generatedIdMap.set(item.id, merged.id);
      return merged;
    });
  const nextGeneratedIds = new Set(nextGeneratedObjects.map((item) => item.id));
  const styledNonTemplateObjects = preserveNonGenerated ? nonTemplateObjects : [];
  const targetObjectsById = new Map(nextGeneratedObjects.map((item) => [item.id, item]));
  const autoTargets = getSceneTemplateAutoTargets(slide, {
    slides: options.slides,
    currentSlideId: options.currentSlideId,
  });
  const generatedTriggers = (templateResult.triggers || [])
    .map((trigger) => {
      const target = generatedIdMap.get(trigger.target) || trigger.target;
      const targetObject = targetObjectsById.get(target) || {};
      return {
        ...trigger,
        target,
        value: getSceneTemplateDefaultTriggerValue(templateId, trigger, targetObject, autoTargets),
      };
    })
    .filter((trigger) => nextGeneratedIds.has(trigger.target));
  const buttonIntroAllowedClickTargets =
    templateId === SCENE_TEMPLATE_BUTTON_INTRO_ID
      ? new Set(nextGeneratedObjects.filter(isButtonIntroInteractiveSlot).map((item) => item.id))
      : null;
  const preservedNonTemplateTriggers = buttonIntroAllowedClickTargets
    ? nonTemplateTriggers.filter(
        (trigger) =>
          (trigger.when || 'onClick') !== 'onClick' ||
          buttonIntroAllowedClickTargets.has(trigger.target)
      )
    : nonTemplateTriggers;
  const manualClickTargets = new Set(
    preservedNonTemplateTriggers
      .filter((trigger) => (trigger.when || 'onClick') === 'onClick')
      .map((trigger) => trigger.target)
  );
  const nextGeneratedTriggers = generatedTriggers.filter(
    (trigger) => !manualClickTargets.has(trigger.target)
  );
  const nextObjects = (
    replaceExisting ? generatedObjects : [...styledNonTemplateObjects, ...nextGeneratedObjects]
  ).map((object) =>
    object?.type === 'button'
      ? { ...object, style: ensureTtkbButtonTextContrast(object.style || {}) }
      : object
  );
  const nextTriggers = replaceExisting
    ? generatedTriggers
    : [...preservedNonTemplateTriggers, ...nextGeneratedTriggers];

  return {
    ...slide,
    sceneTemplateId: templateId,
    sceneTemplatePresetId: presetId,
    sceneTemplateVersion: SCENE_TEMPLATE_VERSION,
    activeLayerId: 'base',
    selectedObjectId: null,
    triggers: nextTriggers,
    objects: nextObjects,
    timeline: syncTimelineWithObjects({ ...slide, objects: nextObjects }),
  };
}

function readStoredEditorHistory(userId, fallbackState) {
  if (typeof window === 'undefined') {
    return { past: [], present: normalizeState(fallbackState), future: [] };
  }
  try {
    const raw = localStorage.getItem(getUserStorageKey(userId));
    if (raw) {
      return { past: [], present: normalizeState(JSON.parse(raw)), future: [] };
    }
  } catch {}
  return { past: [], present: normalizeState(fallbackState), future: [] };
}

function mapStoryboardInteractionTypeToDraftKind(interactionType = '') {
  if (interactionType === 'DragDrop') return 'drag-drop';
  if (interactionType === 'TrueFalse' || interactionType === 'Checkbox') return 'selection';
  if (interactionType === 'Ordering') return 'sequence';
  if (interactionType === 'MediaSlayt') return 'video';
  return null;
}

function pickPrimaryStoryboardInteraction(storyboardPages = []) {
  const priorities = ['DragDrop', 'Ordering', 'TrueFalse', 'Checkbox', 'MediaSlayt', 'Content'];
  return (
    priorities.find((type) => storyboardPages.some((page) => page?.interactionType === type)) ||
    'Content'
  );
}

function extractStoryboardTermLists(storyboardPages = []) {
  const dragTerms = [];
  const answerTerms = [];

  (Array.isArray(storyboardPages) ? storyboardPages : []).forEach((page) => {
    if (Array.isArray(page?.draggableItems)) {
      dragTerms.push(...page.draggableItems);
    }
    if (Array.isArray(page?.dropZones)) {
      answerTerms.push(...page.dropZones.map((zone) => zone?.correctAnswer || '').filter(Boolean));
    }
    if (page?.interactionType === 'Ordering' && Array.isArray(page?.items)) {
      const orderedTexts = [...page.items]
        .sort((a, b) => Number(a?.correctOrder || 0) - Number(b?.correctOrder || 0))
        .map((item) => sanitizePdfText(item?.text || ''))
        .filter(Boolean);
      dragTerms.push(...orderedTexts);
      answerTerms.push(...orderedTexts);
    }
  });

  return {
    draggableTerms: mergePdfTermLists(dragTerms),
    answerTerms: mergePdfTermLists(answerTerms),
  };
}

// eslint-disable-next-line no-unused-vars -- Reserved for the legacy PDF storyboard import path.
function buildPdfSelectionBlueprint(storyboardPages = []) {
  for (const page of Array.isArray(storyboardPages) ? storyboardPages : []) {
    if (page?.interactionType === 'TrueFalse' && Array.isArray(page?.items) && page.items.length) {
      const mcOptions = page.items
        .map((item) => ({
          id: uid(),
          label: sanitizePdfText(item?.statement || ''),
          isCorrect: String(item?.correctAnswer || '').toUpperCase() === 'D',
        }))
        .filter((item) => item.label);
      if (mcOptions.length) {
        return {
          mcMode: 'multi',
          mcQuestion: sanitizePdfText(
            page?.instruction || 'Asagidaki ifadelerden dogru olanlari isaretleyiniz.'
          ),
          mcOptions,
        };
      }
    }

    if (page?.interactionType === 'Checkbox' && Array.isArray(page?.items) && page.items.length) {
      const mcOptions = page.items
        .map((item) => ({
          id: uid(),
          label: sanitizePdfText(item?.text || ''),
          isCorrect: !!item?.correctAnswer,
        }))
        .filter((item) => item.label);
      if (mcOptions.length) {
        return {
          mcMode: 'multi',
          mcQuestion: sanitizePdfText(page?.instruction || 'Uygun kutucuklari isaretleyiniz.'),
          mcOptions,
        };
      }
    }
  }

  return null;
}

function countStoryboardExtractedItems(storyboardPages = []) {
  return (Array.isArray(storyboardPages) ? storyboardPages : []).reduce((total, page) => {
    if (Array.isArray(page?.items)) return total + page.items.length;
    if (Array.isArray(page?.dropZones)) return total + page.dropZones.length;
    return total;
  }, 0);
}

let pdfJsLoaderPromise = null;

async function ensurePdfJsLib() {
  if (typeof window === 'undefined') {
    throw new Error('PDF analizi sadece tarayicida calisir.');
  }
  if (!pdfJsLoaderPromise) {
    pdfJsLoaderPromise = import('pdfjs-dist/legacy/build/pdf')
      .then((module) => module?.default || module)
      .then((lib) => {
        if (!lib?.getDocument) {
          throw new Error('PDF kutuphanesi hazir degil.');
        }
        if (lib.GlobalWorkerOptions) {
          lib.GlobalWorkerOptions.workerSrc =
            (process.env.PUBLIC_URL || '') + '/pdf.worker.min.mjs';
        }
        return lib;
      });
  }
  return pdfJsLoaderPromise;
}

function splitPdfLineSegments(segments = []) {
  const ordered = [...segments].sort((a, b) => a.x - b.x);
  if (!ordered.length) return [];

  const groups = [];
  let currentGroup = [];

  ordered.forEach((segment, index) => {
    if (!currentGroup.length) {
      currentGroup.push(segment);
      return;
    }

    const previous = currentGroup[currentGroup.length - 1];
    const gap = segment.x - (previous.x + previous.width);
    const currentText = currentGroup
      .map((item) => item.text)
      .join(' ')
      .trim();
    const remainingText = ordered
      .slice(index)
      .map((item) => item.text)
      .join(' ')
      .trim();
    const shouldSplit =
      gap > Math.max(120, Math.min(280, (previous.height || 20) * 8)) &&
      currentText.length >= 10 &&
      remainingText.length >= 10;

    if (shouldSplit) {
      groups.push(currentGroup);
      currentGroup = [segment];
      return;
    }

    currentGroup.push(segment);
  });

  if (currentGroup.length) groups.push(currentGroup);
  return groups;
}

function buildPdfTextLines(items = [], viewport = { width: 0, height: 0 }) {
  const buckets = new Map();
  items.forEach((item) => {
    const text = sanitizePdfText(item?.str || '');
    if (!text) return;
    const transform = item?.transform || [];
    const x = Number(transform[4] || 0);
    const y = Number(transform[5] || 0);
    const height = Math.abs(Number(transform[3] || item?.height || 12));
    const key = Math.round(y / 4) * 4;
    if (!buckets.has(key)) {
      buckets.set(key, { y, height, segments: [] });
    }
    buckets.get(key).segments.push({ text, x, width: Number(item?.width || 0) });
  });

  return [...buckets.values()]
    .flatMap((row) => {
      const segments = row.segments.sort((a, b) => a.x - b.x);
      return splitPdfLineSegments(segments).map((group) => {
        let lineText = '';
        let cursor = null;
        let maxWidth = 0;
        group.forEach((segment, index) => {
          const gap = cursor == null ? 0 : segment.x - cursor;
          const needsSpace = index > 0 && gap > 2;
          lineText += `${needsSpace ? ' ' : ''}${segment.text}`;
          cursor = segment.x + segment.width;
          maxWidth = Math.max(maxWidth, cursor);
        });
        const minX = Math.min(...group.map((segment) => segment.x));
        return {
          text: sanitizePdfText(lineText),
          x: minX,
          y: row.y,
          height: row.height,
          width: Math.max(0, maxWidth - minX),
          pageWidth: Number(viewport?.width || 0),
          pageHeight: Number(viewport?.height || 0),
          tokens: group.map((segment) => ({
            text: segment.text,
            x: segment.x,
            width: segment.width,
            height: row.height,
          })),
        };
      });
    })
    .filter((line) => line.text)
    .sort((a, b) => b.y - a.y || a.x - b.x);
}

function detectPdfMarker(lines = []) {
  const candidates = lines.slice(0, 8).map((line) => normalizePdfText(line.text));
  for (const line of candidates) {
    const eIcerikMatch = line.match(/(^|\b)(\d+)\s*[.)-]?\s*(e\s*-?\s*icerik|icerik|etkinlik)\b/);
    if (eIcerikMatch) {
      const order = Number(eIcerikMatch[2]) || 0;
      return {
        key: `${order}-etkinlik`,
        label: `${order}. Etkinlik`,
        index: order,
        kindHint: 'activity',
      };
    }
    const videoMatch = line.match(/(^|\b)(\d+)\s*[.)-]?\s*video\b/);
    if (videoMatch) {
      const order = Number(videoMatch[2]) || 0;
      return {
        key: `${order}-video`,
        label: `${order}. Video`,
        index: order,
        kindHint: 'video',
      };
    }
  }
  return null;
}

function buildFallbackPdfGroups(pages = []) {
  const groups = [];
  let currentGroup = null;

  pages.forEach((page, index) => {
    const pageKind = detectPdfDraftKind(page.lines || [], 1, page.marker || null);
    const readingLike = pageKind === 'reading' || pageKind === 'unknown';
    const shouldStartNewGroup = (() => {
      if (!currentGroup) return true;
      const currentReadingOnly = currentGroup.pageKinds.every(
        (kind) => kind === 'reading' || kind === 'unknown'
      );
      if (currentReadingOnly && readingLike) return false;
      if (currentReadingOnly && !readingLike && !currentGroup.hasTerminalInteractivePage) {
        currentGroup.hasTerminalInteractivePage = true;
        return false;
      }
      return true;
    })();

    if (shouldStartNewGroup) {
      currentGroup = {
        id: uid(),
        markerKey: `fallback-${index + 1}`,
        markerLabel: `Etkinlik ${groups.length + 1}`,
        markerIndex: groups.length + 1,
        pages: [],
        pageKinds: [],
        hasTerminalInteractivePage: false,
      };
      groups.push(currentGroup);
    }

    currentGroup.pages.push(page);
    currentGroup.pageKinds.push(pageKind);
  });

  return groups;
}

function inferPdfDraftTitle(lines = [], fallback = 'PDF Etkinligi') {
  const ignored = [
    'tema',
    'sozun ezgisi',
    'dunden bugune',
    'kelimelerin ritmi',
    'e-icerik',
    'video',
  ];
  const strongLine = lines.find((line) => {
    const normalized = normalizePdfText(line.text);
    if (!normalized || normalized.length < 8 || normalized.length > 160) return false;
    if (ignored.some((word) => normalized.includes(word))) return false;
    return true;
  });
  return strongLine?.text || fallback;
}

function detectPdfDraftStatus(kind = 'unknown', details = {}) {
  if (kind === 'drag-drop' && details.draggableTerms?.length && details.answerTerms?.length)
    return 'ready';
  if (kind === 'drag-drop' && details.draggableTerms?.length) return 'review';
  if (kind === 'selection') return 'review';
  if (kind === 'reading' || kind === 'sequence' || kind === 'video') return 'review';
  return 'blocked';
}

function inferPdfSelectionAnchors(lines = [], pageWidth = 1920, pageHeight = 1080) {
  const ignored = [
    'tema',
    'dunden bugune',
    'kutucugu',
    'isaretleyiniz',
    'e-icerik',
    'dogru eslestirme',
    'suruklenebilir',
    'yerlere uygun',
    'gunumuz turkcesiyle',
  ];
  const candidates = (lines || [])
    .map((line) => {
      const normalized = normalizePdfText(line.text);
      return { ...line, normalized };
    })
    .filter((line) => {
      if (!line.normalized || line.normalized.length < 8) return false;
      if (ignored.some((token) => line.normalized.includes(token))) return false;
      if (line.x > pageWidth * 0.16) return false;
      if (line.width < pageWidth * 0.22) return false;
      if (line.y < pageHeight * 0.22 || line.y > pageHeight * 0.88) return false;
      if (/^[dy]$/.test(line.normalized)) return false;
      return true;
    })
    .sort((a, b) => a.y - b.y);

  const anchors = [];
  candidates.forEach((line) => {
    const existing = anchors[anchors.length - 1];
    if (existing && Math.abs(existing.stageY - line.y) < Math.max(18, line.height * 0.8)) {
      existing.text = `${existing.text} ${line.text}`.trim();
      existing.width = Math.max(existing.width, line.x + line.width - existing.x);
      existing.height = Math.max(existing.height, line.height);
      return;
    }
    anchors.push({
      text: line.text,
      x: line.x,
      y: line.y,
      width: line.width,
      height: line.height || 28,
      stageY: line.y,
      order: anchors.length + 1,
    });
  });

  return anchors.slice(0, 16);
}

function shouldUsePdfBottomOrigin(lines = [], pageHeight = 1080) {
  if (!Array.isArray(lines) || !lines.length) return false;
  const values = lines
    .map((line) => Number(line?.y || 0))
    .filter((value) => Number.isFinite(value));
  if (!values.length) return false;
  const maxY = Math.max(...values);
  return maxY > pageHeight * 0.5;
}

function getPdfStageRectForLines(
  lines = [],
  pageWidth = 1365,
  pageHeight = 768,
  paddingX = 18,
  paddingY = 14
) {
  if (!Array.isArray(lines) || !lines.length) return null;
  const useBottomOrigin = shouldUsePdfBottomOrigin(lines, pageHeight);
  const points = lines.map((line) => {
    const x = Number(line?.x || 0);
    const width = Math.max(12, Number(line?.width || 0));
    const height = Math.max(12, Number(line?.height || 0));
    const y = useBottomOrigin
      ? Math.max(0, pageHeight - Number(line?.y || 0) - height)
      : Math.max(0, Number(line?.y || 0));
    return { x, y, width, height };
  });
  const minX = Math.max(0, Math.min(...points.map((point) => point.x)) - paddingX);
  const minY = Math.max(0, Math.min(...points.map((point) => point.y)) - paddingY);
  const maxX = Math.min(
    pageWidth,
    Math.max(...points.map((point) => point.x + point.width)) + paddingX
  );
  const maxY = Math.min(
    pageHeight,
    Math.max(...points.map((point) => point.y + point.height)) + paddingY
  );
  return {
    x: minX,
    y: minY,
    width: Math.max(24, maxX - minX),
    height: Math.max(24, maxY - minY),
  };
}

function getPdfQuestionAnchors(page = {}) {
  const width = page.width || 1920;
  const height = page.height || 1080;
  const anchors = Array.isArray(page?.layoutHints?.questionAnchors)
    ? page.layoutHints.questionAnchors
    : [];
  return anchors
    .map((anchor, index) => ({
      text: sanitizePdfText(anchor?.text || ''),
      x: clamp(Number(anchor?.x || 0), 0, width),
      y: clamp(Number(anchor?.y || 0), 0, height),
      width: clamp(Number(anchor?.width || 0), 24, width),
      height: clamp(Number(anchor?.height || 0), 20, height),
      stageY: clamp(Number(anchor?.y || 0), 0, height),
      order: Math.max(1, Math.round(Number(anchor?.order || index + 1))),
    }))
    .sort((a, b) => a.order - b.order || a.y - b.y || a.x - b.x);
}

function getPdfDragPoolRect(page = {}) {
  const lines = Array.isArray(page.lines) ? page.lines : [];
  const width = page.width || 1920;
  const height = page.height || 1080;
  const hintRect = normalizePdfHintRect(page?.layoutHints?.dragPoolRect, width, height, 28);
  if (hintRect) {
    return { ...hintRect, headerLine: null, source: 'layout' };
  }
  const headerLine = lines.find((line) =>
    normalizePdfText(line.text).includes('suruklenebilir ogeler')
  );
  if (!headerLine) return null;

  const answerLine = lines.find((line) => normalizePdfText(line.text).includes('dogru eslestirme'));
  const headerY = Number(headerLine?.y || 0);
  const headerX = Number(headerLine?.x || width * 0.68);
  const answerY = answerLine ? Number(answerLine?.y || 0) : height;

  // Content lines are those below the header, in the same X-column, and above the answer section
  const contentLines = lines.filter((line) => {
    const ly = Number(line?.y || 0);
    const lx = Number(line?.x || 0);
    if (ly <= headerY + (headerLine?.height || 12)) return false;
    if (answerLine && ly >= answerY) return false;
    return lx >= headerX - width * 0.03;
  });

  const contentRect = contentLines.length
    ? getPdfStageRectForLines(contentLines, width, height, 16, 12)
    : null;
  const headerBottom = clamp(headerY + Number(headerLine?.height || 0) + 10, 0, height - 80);
  const x = clamp(Math.max(headerX - 18, width * 0.58), 0, width - 160);
  const rightEdge = clamp(
    contentRect ? contentRect.x + contentRect.width + 18 : width - 24,
    x + 180,
    width - 20
  );
  const bottom = clamp(
    contentRect
      ? contentRect.y + contentRect.height + 8
      : headerBottom + Math.max(160, height * 0.3),
    headerBottom + 120,
    height - 20
  );

  return {
    x,
    y: headerBottom,
    width: Math.max(180, rightEdge - x),
    height: Math.max(120, bottom - headerBottom),
    headerLine,
  };
}

// eslint-disable-next-line no-unused-vars -- Kept for future PDF raster cleanup heuristics.
function detectCanvasContentBounds(canvas, threshold = 244, sampleStep = 3) {
  if (!canvas?.width || !canvas?.height) return null;
  const context = canvas.getContext('2d', { willReadFrequently: true });
  if (!context) return null;
  const { width, height } = canvas;
  const imageData = context.getImageData(0, 0, width, height).data;
  let minX = width;
  let minY = height;
  let maxX = -1;
  let maxY = -1;

  for (let y = 0; y < height; y += sampleStep) {
    for (let x = 0; x < width; x += sampleStep) {
      const index = (y * width + x) * 4;
      const r = imageData[index];
      const g = imageData[index + 1];
      const b = imageData[index + 2];
      const a = imageData[index + 3];
      if (a < 8) continue;
      if (r >= threshold && g >= threshold && b >= threshold) continue;
      if (x < minX) minX = x;
      if (y < minY) minY = y;
      if (x > maxX) maxX = x;
      if (y > maxY) maxY = y;
    }
  }

  if (maxX < 0 || maxY < 0) return null;
  const padX = Math.max(20, Math.round(width * 0.02));
  const padY = Math.max(20, Math.round(height * 0.02));
  return {
    x: Math.max(0, minX - padX),
    y: Math.max(0, minY - padY),
    width: Math.min(width, maxX - minX + padX * 2),
    height: Math.min(height, maxY - minY + padY * 2),
  };
}
function mapPdfLinesToStage(lines = [], transform = {}) {
  const scaleX = Number(transform.scaleX || 1);
  const scaleY = Number(transform.scaleY || 1);
  const offsetX = Number(transform.offsetX || 0);
  const offsetY = Number(transform.offsetY || 0);
  const pageHeight = Number(
    lines.find((line) => Number(line?.pageHeight || 0) > 0)?.pageHeight || 0
  );
  const useBottomOrigin = pageHeight > 0 ? shouldUsePdfBottomOrigin(lines, pageHeight) : false;
  return (lines || []).map((line) => ({
    ...line,
    x: offsetX + Number(line?.x || 0) * scaleX,
    y: useBottomOrigin
      ? offsetY +
        Math.max(0, pageHeight - (Number(line?.y || 0) + Math.max(1, Number(line?.height || 0)))) *
          scaleY
      : offsetY + Number(line?.y || 0) * scaleY,
    width: Math.max(1, Number(line?.width || 0) * scaleX),
    height: Math.max(1, Number(line?.height || 0) * scaleY),
    tokens: (Array.isArray(line?.tokens) ? line.tokens : []).map((token) => ({
      ...token,
      x: offsetX + Number(token?.x || 0) * scaleX,
      y: useBottomOrigin
        ? offsetY +
          Math.max(
            0,
            pageHeight -
              (Number(line?.y || 0) + Math.max(1, Number(token?.height || line?.height || 0)))
          ) *
            scaleY
        : offsetY + Number(line?.y || 0) * scaleY,
      width: Math.max(1, Number(token?.width || 0) * scaleX),
      height: Math.max(1, Number(token?.height || 0) * scaleY),
    })),
  }));
}

function paintPdfCleanupRect(context, rect, bgColor = null) {
  if (!context || !rect) return;
  // Use provided bgColor or default to white if not sampling
  context.fillStyle = bgColor || '#ffffff';
  context.fillRect(
    Math.max(0, rect.x),
    Math.max(0, rect.y),
    Math.max(1, rect.width),
    Math.max(1, rect.height)
  );
}

function samplePdfCanvasBackgroundColor(canvas, nearRect) {
  if (!canvas?.width || !canvas?.height || !nearRect) return '#ffffff';
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) return '#ffffff';
  const sampleX = Math.max(0, Math.round(nearRect.x - 12));
  const sampleY = Math.max(0, Math.round(nearRect.y + (nearRect.height || 0) * 0.5 - 4));
  const sampleW = Math.min(8, canvas.width - sampleX);
  const sampleH = Math.min(8, canvas.height - sampleY);
  if (sampleW < 1 || sampleH < 1) return '#ffffff';
  const data = ctx.getImageData(sampleX, sampleY, sampleW, sampleH).data;
  let sumR = 0,
    sumG = 0,
    sumB = 0,
    count = 0;
  for (let i = 0; i < data.length; i += 4) {
    if (data[i + 3] < 20) continue;
    sumR += data[i];
    sumG += data[i + 1];
    sumB += data[i + 2];
    count++;
  }
  if (!count) return '#ffffff';
  const r = Math.round(sumR / count),
    g = Math.round(sumG / count),
    b = Math.round(sumB / count);
  return `rgb(${r},${g},${b})`;
}

function detectPdfGreenCells(canvas, region = {}) {
  if (!canvas?.width || !canvas?.height) return [];
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  if (!ctx) return [];
  const cw = canvas.width,
    ch = canvas.height;
  const sx = Math.max(0, Math.floor(region.x ?? cw * 0.5));
  const sy = Math.max(0, Math.floor(region.y ?? 0));
  const ex = Math.min(cw, Math.ceil(sx + (region.width ?? cw * 0.5)));
  const ey = Math.min(ch, Math.ceil(sy + (region.height ?? ch)));
  const rw = ex - sx,
    rh = ey - sy;
  if (rw < 2 || rh < 2) return [];
  const data = ctx.getImageData(sx, sy, rw, rh).data;
  const step = 2;
  const gh = Math.ceil(rh / step);
  const gw = Math.ceil(rw / step);
  const greenGrid = new Uint8Array(gh * gw);
  for (let gy = 0; gy < gh; gy++) {
    for (let gx = 0; gx < gw; gx++) {
      const px = gx * step,
        py = gy * step;
      const i = (py * rw + px) * 4;
      const r = data[i],
        g = data[i + 1],
        b = data[i + 2],
        a = data[i + 3];
      if (a < 20) continue;
      if (r > 235 && g > 235 && b > 235) continue; // white
      if (r < 20 && g < 20 && b < 20) continue; // black text
      if (g > 100 && g > r + 15 && g > b - 30) {
        greenGrid[gy * gw + gx] = 1;
      }
    }
  }
  const cells = [];
  let inRun = false,
    runStartY = 0,
    runMinX = gw,
    runMaxX = -1;
  for (let gy = 0; gy <= gh; gy++) {
    let rowMinX = gw,
      rowMaxX = -1;
    if (gy < gh) {
      for (let gx = 0; gx < gw; gx++) {
        if (greenGrid[gy * gw + gx]) {
          rowMinX = Math.min(rowMinX, gx);
          rowMaxX = Math.max(rowMaxX, gx);
        }
      }
    }
    const hasGreen = rowMaxX >= 0;
    if (hasGreen) {
      if (!inRun) {
        inRun = true;
        runStartY = gy;
        runMinX = rowMinX;
        runMaxX = rowMaxX;
      } else {
        runMinX = Math.min(runMinX, rowMinX);
        runMaxX = Math.max(runMaxX, rowMaxX);
      }
    } else if (inRun) {
      const cellH = (gy - runStartY) * step;
      const cellW = (runMaxX - runMinX + 1) * step;
      if (cellH >= 6 && cellW >= 6) {
        const cx = sx + runMinX * step,
          cy = sy + runStartY * step;
        cells.push({
          x: cx,
          y: cy,
          width: cellW,
          height: cellH,
          centerX: cx + cellW / 2,
          centerY: cy + cellH / 2,
        });
      }
      inRun = false;
      runMinX = gw;
      runMaxX = -1;
    }
  }
  return cells;
}

function detectRedAnnotationBounds(canvas, region = {}) {
  if (!canvas?.width || !canvas?.height) return null;
  const context = canvas.getContext('2d', { willReadFrequently: true });
  if (!context) return null;
  const width = canvas.width;
  const height = canvas.height;
  const startX = Math.max(0, Math.floor(region.x ?? width * 0.55));
  const startY = Math.max(0, Math.floor(region.y ?? height * 0.72));
  const endX = Math.min(
    width,
    Math.ceil((region.x ?? width * 0.55) + (region.width ?? width * 0.4))
  );
  const endY = Math.min(
    height,
    Math.ceil((region.y ?? height * 0.72) + (region.height ?? height * 0.24))
  );
  const imageData = context.getImageData(
    startX,
    startY,
    Math.max(1, endX - startX),
    Math.max(1, endY - startY)
  ).data;
  let minX = endX;
  let minY = endY;
  let maxX = -1;
  let maxY = -1;
  for (let y = 0; y < endY - startY; y += 2) {
    for (let x = 0; x < endX - startX; x += 2) {
      const index = (y * (endX - startX) + x) * 4;
      const r = imageData[index];
      const g = imageData[index + 1];
      const b = imageData[index + 2];
      const a = imageData[index + 3];
      if (a < 20) continue;
      if (!(r > 160 && g < 170 && b < 190 && r - g > 35)) continue;
      minX = Math.min(minX, startX + x);
      minY = Math.min(minY, startY + y);
      maxX = Math.max(maxX, startX + x);
      maxY = Math.max(maxY, startY + y);
    }
  }
  if (maxX < 0 || maxY < 0) return null;
  return {
    x: Math.max(0, minX - 18),
    y: Math.max(0, minY - 14),
    width: Math.min(width, maxX - minX + 36),
    height: Math.min(height, maxY - minY + 28),
  };
}

function estimatePdfRowHeight(anchors = [], pageHeight = 768) {
  const gaps = anchors
    .slice(1)
    .map((anchor, index) => anchor.stageY - anchors[index].stageY)
    .filter((gap) => gap > 24 && gap < pageHeight * 0.25);
  if (!gaps.length) return clamp(pageHeight * 0.08, 42, 86);
  const avgGap = gaps.reduce((sum, gap) => sum + gap, 0) / gaps.length;
  return clamp(avgGap * 0.78, 40, 88);
}

function clusterPdfColumnCenters(values = [], tolerance = 120) {
  const sorted = [...values]
    .map((value) => Number(value))
    .filter((value) => Number.isFinite(value))
    .sort((a, b) => a - b);
  if (!sorted.length) return [];

  const clusters = [[sorted[0]]];
  for (let index = 1; index < sorted.length; index += 1) {
    const value = sorted[index];
    const current = clusters[clusters.length - 1];
    const currentCenter = current.reduce((sum, item) => sum + item, 0) / current.length;
    if (Math.abs(value - currentCenter) <= tolerance) {
      current.push(value);
    } else {
      clusters.push([value]);
    }
  }

  return clusters.map((cluster) => getMedian(cluster));
}

function compactPdfColumnLabel(value = '', index = 0) {
  const text = sanitizePdfText(value);
  if (!text) return `${index + 1}`;
  const roman = text.match(/\b([ivxlcdm]+|\d+)\b/i)?.[1];
  if (roman) return roman.toUpperCase();
  if (text.length <= 14) return text;
  const words = text.split(/\s+/).filter(Boolean);
  if (words.length >= 2) {
    const initials = words
      .slice(0, 2)
      .map((word) => word[0])
      .join('');
    if (initials.length >= 2) return initials.toUpperCase();
  }
  return text.slice(0, 10).trim();
}

function stripPdfAnchorListPrefix(value = '') {
  return sanitizePdfText(value)
    .replace(/^\s*(?:(?:\(?\d+\)?|\(?[a-zçğıöşü]\)?)\s*[.)\-:]|[-•●▪])\s*/iu, '')
    .trim();
}

function stripTrailingCheckMark(value = '') {
  return sanitizePdfText(value)
    .replace(/\s+[☑☐✓✔✗✘]\s*$/u, '')
    .trim();
}

function inferPdfTableChoiceColumns(lines = [], centers = [], width = 1920, height = 1080) {
  if (!Array.isArray(centers) || !centers.length) return [];
  const candidateRows = (Array.isArray(lines) ? lines : [])
    .filter((line) => Number(line?.y || 0) < height * 0.45)
    .filter((line) => {
      const normalized = normalizePdfText(line?.text || '');
      return (
        normalized &&
        !normalized.includes('isaretleyiniz') &&
        !normalized.includes('kutucugu') &&
        !normalized.includes('kutucuklarini') &&
        !normalized.includes('tema') &&
        !/[✓✔☑]/.test(line?.text || '')
      );
    });

  return centers.map((center, index) => {
    let bestToken = null;
    let bestDistance = Number.POSITIVE_INFINITY;
    candidateRows.forEach((line) => {
      (Array.isArray(line?.tokens) ? line.tokens : []).forEach((token) => {
        const tokenText = sanitizePdfText(token?.text || '');
        if (!tokenText || /[✓✔☑]/.test(tokenText)) return;
        const tokenCenter = Number(token?.x || 0) + Math.max(8, Number(token?.width || 0)) / 2;
        const distance = Math.abs(tokenCenter - center);
        if (distance < bestDistance && distance <= 180) {
          bestDistance = distance;
          bestToken = tokenText;
        }
      });
    });

    return {
      key: `col_${index + 1}`,
      label: compactPdfColumnLabel(bestToken || '', index),
      fullLabel: sanitizePdfText(bestToken || ''),
      center,
    };
  });
}

function findPdfAnchorLineForText(lines = [], target = '', usedLineIds = new Set()) {
  const normalizedTarget = normalizePdfText(target);
  if (!normalizedTarget) return null;

  const candidates = (Array.isArray(lines) ? lines : [])
    .filter((line) => !usedLineIds.has(line?.id))
    .map((line) => {
      const cleanedText = stripTrailingCheckMark(
        stripPdfAnchorListPrefix(sanitizePdfText(line?.text || ''))
      );
      const normalizedLine = normalizePdfText(cleanedText);
      const exact = normalizedLine === normalizedTarget;
      const contains =
        normalizedLine.includes(normalizedTarget) || normalizedTarget.includes(normalizedLine);
      return {
        line,
        exact,
        contains,
        score: Math.abs(normalizedLine.length - normalizedTarget.length),
      };
    })
    .filter((entry) => entry.exact || entry.contains)
    .sort((a, b) => {
      if (a.exact !== b.exact) return a.exact ? -1 : 1;
      if (a.score !== b.score) return a.score - b.score;
      return a.line.y - b.line.y || a.line.x - b.line.x;
    });

  return candidates[0]?.line || null;
}

function buildPdfSelectionLayoutFromStoryboard(draft = {}, page = {}) {
  const storyboardPage = (Array.isArray(draft?.storyboardPages) ? draft.storyboardPages : []).find(
    (entry) => Number(entry?.pageNumber || 0) === Number(page?.pageNumber || 0)
  );
  if (!storyboardPage) return null;

  const lines = Array.isArray(page?.lines) ? page.lines : [];
  const width = page.width || 1920;
  const height = page.height || 1080;
  const usedLineIds = new Set();

  if (
    storyboardPage.interactionType === 'Checkbox' &&
    Array.isArray(storyboardPage.items) &&
    storyboardPage.items.length
  ) {
    const anchors = storyboardPage.items
      .map((item, index) => {
        const line = findPdfAnchorLineForText(lines, item?.text || '', usedLineIds);
        if (!line) return null;
        usedLineIds.add(line.id);
        return {
          text: sanitizePdfText(item?.text || line.text || ''),
          x: Number(line.x || 0),
          y: Number(line.y || 0),
          width: Number(line.width || 0),
          height: Math.max(20, Number(line.height || 28)),
          stageY: Number(line.y || 0),
          order: index + 1,
        };
      })
      .filter(Boolean)
      .sort((a, b) => a.stageY - b.stageY || a.x - b.x);

    if (!anchors.length) return null;

    const rowHeight = estimatePdfRowHeight(anchors, height);
    const candidateXs = (Array.isArray(page?.annotationCells) ? page.annotationCells : [])
      .map((cell) => Number(cell?.centerX || 0))
      .filter((value) => value > width * 0.35);
    const columnCenter = candidateXs.length ? getMedian(candidateXs) : width * 0.79;
    const columnWidth = clamp(width * 0.12, 78, width * 0.16);
    const tickLeft = clamp(columnCenter - columnWidth / 2, 0, width - columnWidth);
    const answers = Object.fromEntries(
      storyboardPage.items.map((item, index) => [
        `pdf-q-${index + 1}`,
        item?.correctAnswer ? 'tick' : null,
      ])
    );

    return {
      mode: 'single-check',
      anchors,
      rowHeight,
      columnWidth,
      columns: [{ key: 'tick', left: tickLeft, width: columnWidth }],
      answers,
    };
  }

  if (
    storyboardPage.interactionType === 'TrueFalse' &&
    Array.isArray(storyboardPage.items) &&
    storyboardPage.items.length
  ) {
    const anchors = storyboardPage.items
      .map((item, index) => {
        const line = findPdfAnchorLineForText(lines, item?.statement || '', usedLineIds);
        if (!line) return null;
        usedLineIds.add(line.id);
        return {
          text: sanitizePdfText(item?.statement || line.text || ''),
          x: Number(line.x || 0),
          y: Number(line.y || 0),
          width: Number(line.width || 0),
          height: Math.max(20, Number(line.height || 28)),
          stageY: Number(line.y || 0),
          order: index + 1,
        };
      })
      .filter(Boolean)
      .sort((a, b) => a.stageY - b.stageY || a.x - b.x);

    if (!anchors.length) return null;

    const headerTokens = lines
      .flatMap((line) =>
        Array.isArray(line?.tokens) ? line.tokens.map((token) => ({ ...token, rowY: line.y })) : []
      )
      .map((token) => ({ ...token, normalized: normalizePdfText(token?.text || '') }));
    const dToken = headerTokens.find((token) => token.normalized === 'd');
    const yToken = headerTokens.find(
      (token) => token.normalized === 'y' && Number(token?.x || 0) > Number(dToken?.x || 0)
    );
    const rowHeight = estimatePdfRowHeight(anchors, height);
    const columnWidth = clamp(
      (Math.abs(Number(yToken?.x || width * 0.84) - Number(dToken?.x || width * 0.74)) ||
        width * 0.1) * 0.82,
      54,
      width * 0.14
    );
    const dLeft = clamp(
      (Number(dToken?.x || width * 0.74) || 0) - columnWidth * 0.45,
      0,
      width - columnWidth
    );
    const yLeft = clamp(
      (Number(yToken?.x || width * 0.84) || 0) - columnWidth * 0.45,
      0,
      width - columnWidth
    );
    const answers = Object.fromEntries(
      storyboardPage.items.map((item, index) => [
        `pdf-q-${index + 1}`,
        normalizePdfText(item?.correctAnswer || '') === 'd' ? 'd' : 'y',
      ])
    );

    return {
      mode: 'binary',
      anchors,
      rowHeight,
      columnWidth,
      columns: [
        { key: 'd', left: dLeft, width: columnWidth },
        { key: 'y', left: yLeft, width: columnWidth },
      ],
      answers,
    };
  }

  return null;
}

function detectPdfSelectionLayout(page = {}) {
  const width = page.width || 1365;
  const height = page.height || 768;
  const lines = Array.isArray(page.lines) ? page.lines : [];
  const layoutAnchors = getPdfQuestionAnchors(page);
  const numberedAnchors = extractPdfQuestionAnchors(lines, height);
  const anchors = layoutAnchors.length
    ? layoutAnchors
    : numberedAnchors.length
      ? numberedAnchors
      : inferPdfSelectionAnchors(lines, width, height);
  if (!anchors.length) return null;

  const normalizedLines = lines.map((line) => ({
    ...line,
    normalized: normalizePdfText(line.text),
  }));
  const dLine = normalizedLines.find((line) => line.normalized === 'd');
  const yLine = normalizedLines.find(
    (line) => line.normalized === 'y' && (!dLine || line.x > dLine.x + 12)
  );
  const rowHeight = estimatePdfRowHeight(anchors, height);
  const answers = {};
  const textMarkLines = normalizedLines
    .map((line) => {
      const stageY = Math.max(0, Number(line.y || 0));
      const markText = sanitizePdfText(line.text || '');
      const centerX = Number(line.x || 0) + Math.max(8, Number(line.width || 0)) / 2;
      const centerY = stageY + Math.max(12, Number(line.height || 0)) / 2;
      return { ...line, stageY, markText, centerX, centerY };
    })
    .filter((line) => !!line.markText && /[✓✔☑√]/.test(line.markText));

  // Augment with annotation/pixel-detected cells (non-text tick detection)
  const annotCells = Array.isArray(page.annotationCells) ? page.annotationCells : [];
  const annotMarkLines = annotCells.map((ann) => ({
    stageY: ann.centerY - (ann.stageH || 0) / 2,
    markText: '✓',
    centerX: ann.centerX,
    centerY: ann.centerY,
    checked: ann.checked !== false,
  }));
  const markLines = [...textMarkLines, ...annotMarkLines.filter((a) => a.checked)];

  if (dLine && yLine) {
    const rawGap = Math.abs(Number(yLine.x || 0) - Number(dLine.x || 0));
    const columnWidth = clamp(rawGap * 0.82, 54, width * 0.14);
    const dLeft = clamp(Number(dLine.x || 0) - columnWidth * 0.45, 0, width - columnWidth);
    const yLeft = clamp(Number(yLine.x || 0) - columnWidth * 0.45, 0, width - columnWidth);
    const dCenter = dLeft + columnWidth / 2;
    const yCenter = yLeft + columnWidth / 2;

    anchors.forEach((anchor, index) => {
      const questionId = `pdf-q-${index + 1}`;
      const rowTop = Math.max(0, anchor.stageY - rowHeight * 0.18);
      const rowBottom = rowTop + rowHeight;
      const markLine = markLines.find(
        (line) => line.centerY >= rowTop && line.centerY <= rowBottom
      );
      if (!markLine) return;
      answers[questionId] =
        Math.abs(markLine.centerX - dCenter) <= Math.abs(markLine.centerX - yCenter) ? 'd' : 'y';
    });

    return {
      mode: 'binary',
      anchors,
      rowHeight,
      columnWidth,
      columns: [
        { key: 'd', left: dLeft, width: columnWidth },
        { key: 'y', left: yLeft, width: columnWidth },
      ],
      answers,
    };
  }

  const clusteredCenters = clusterPdfColumnCenters(
    markLines.filter((line) => line.centerX > width * 0.35).map((line) => line.centerX),
    Math.max(72, width * 0.05)
  );
  if (clusteredCenters.length >= 2) {
    const columnDefs = inferPdfTableChoiceColumns(lines, clusteredCenters, width, height);
    const gapValues = clusteredCenters
      .slice(1)
      .map((center, index) => center - clusteredCenters[index])
      .filter((gap) => gap > 24);
    const medianGap = gapValues.length ? getMedian(gapValues) : width * 0.14;
    const columnWidth = clamp(medianGap * 0.72, 84, width * 0.18);
    const columns = columnDefs.map((column, index) => ({
      key: column.key,
      label: column.label || `${index + 1}`,
      fullLabel: column.fullLabel || column.label || `${index + 1}`,
      left: clamp(column.center - columnWidth / 2, 0, width - columnWidth),
      width: columnWidth,
      center: column.center,
    }));

    anchors.forEach((anchor, index) => {
      const questionId = `pdf-q-${index + 1}`;
      const rowTop = Math.max(0, anchor.stageY - rowHeight * 0.18);
      const rowBottom = rowTop + rowHeight;
      const rowMarks = markLines.filter(
        (line) => line.centerY >= rowTop && line.centerY <= rowBottom
      );
      if (!rowMarks.length) {
        answers[questionId] = null;
        return;
      }
      const match = columns.reduce((best, column) => {
        const distance = Math.min(
          ...rowMarks.map((line) => Math.abs(line.centerX - column.center))
        );
        if (!best || distance < best.distance) return { key: column.key, distance };
        return best;
      }, null);
      answers[questionId] = match?.key || null;
    });

    return {
      mode: 'table-choice',
      anchors,
      rowHeight,
      columnWidth,
      columns,
      answers,
    };
  }

  const promptText = normalizePdfText(
    lines
      .slice(0, 12)
      .map((line) => line.text)
      .join(' ')
  );
  const isSingleTickMode =
    promptText.includes('kutucugu') || promptText.includes('isaretleyiniz') || markLines.length > 0;
  if (!isSingleTickMode) return null;

  const candidateXs = markLines
    .filter((line) => line.centerX > width * 0.55)
    .map((line) => line.centerX);
  const columnCenter = candidateXs.length ? getMedian(candidateXs) : width * 0.78;
  const columnWidth = clamp(width * 0.12, 78, width * 0.16);
  const tickLeft = clamp(columnCenter - columnWidth / 2, 0, width - columnWidth);

  anchors.forEach((anchor, index) => {
    const questionId = `pdf-q-${index + 1}`;
    const rowTop = Math.max(0, anchor.stageY - rowHeight * 0.18);
    const rowBottom = rowTop + rowHeight;
    const markLine = markLines.find((line) => line.centerY >= rowTop && line.centerY <= rowBottom);
    answers[questionId] = markLine ? 'tick' : null;
  });

  return {
    mode: 'single-check',
    anchors,
    rowHeight,
    columnWidth,
    columns: [{ key: 'tick', left: tickLeft, width: columnWidth }],
    answers,
  };
}

async function renderPdfPageAsset(page, fileName, pageIndex, lines = [], onProgress = () => {}) {
  const viewport = page.getViewport({ scale: 1.4 });
  const canvas = document.createElement('canvas');
  canvas.width = Math.round(viewport.width);
  canvas.height = Math.round(viewport.height);
  const context = canvas.getContext('2d', { alpha: false });
  await page.render({ canvasContext: context, viewport }).promise;
  const outputCanvas = document.createElement('canvas');
  outputCanvas.width = 1920;
  outputCanvas.height = 1080;
  const outputContext = outputCanvas.getContext('2d', { alpha: false });
  outputContext.fillStyle = '#ffffff';
  outputContext.fillRect(0, 0, outputCanvas.width, outputCanvas.height);

  const sourceRatio = canvas.width / canvas.height;
  const targetRatio = outputCanvas.width / outputCanvas.height;
  const drawWidth =
    sourceRatio > targetRatio ? outputCanvas.width : Math.round(outputCanvas.height * sourceRatio);
  const drawHeight =
    sourceRatio > targetRatio ? Math.round(outputCanvas.width / sourceRatio) : outputCanvas.height;
  const drawX = Math.round((outputCanvas.width - drawWidth) / 2);
  const drawY = Math.round((outputCanvas.height - drawHeight) / 2);
  outputContext.drawImage(canvas, drawX, drawY, drawWidth, drawHeight);
  const transform = {
    offsetX: drawX,
    offsetY: drawY,
    scaleX: drawWidth / Math.max(1, canvas.width),
    scaleY: drawHeight / Math.max(1, canvas.height),
  };
  const stageLines = mapPdfLinesToStage(lines, transform);
  const layoutHints = null;
  const stagePage = {
    width: 1920,
    height: 1080,
    lines: stageLines,
    layoutHints,
    annotationCells: detectPdfGreenCells(canvas).map((cell) => ({
      centerX: (cell.x + cell.width / 2) * transform.scaleX + transform.offsetX,
      centerY: (cell.y + cell.height / 2) * transform.scaleY + transform.offsetY,
      stageH: cell.height * transform.scaleY,
      checked: true,
    })),
  };

  const markerLines = stageLines.filter((line) => {
    const normalized = normalizePdfText(line.text);
    return normalized.includes('e-icerik') || /^\d+\s*[.)-]?\s*video\b/.test(normalized);
  });
  markerLines.forEach((line) => {
    const rect = getPdfStageRectForLines([line], 1920, 1080, 28, 18);
    const bgColor = samplePdfCanvasBackgroundColor(outputCanvas, rect);
    paintPdfCleanupRect(outputContext, rect, bgColor);
  });

  const selectionLayout = detectPdfSelectionLayout(stagePage);
  if (selectionLayout) {
    const columnHeight = clamp(
      (selectionLayout.anchors[selectionLayout.anchors.length - 1]?.stageY || 0) +
        selectionLayout.rowHeight -
        Math.max(0, selectionLayout.anchors[0]?.stageY || 0) +
        selectionLayout.rowHeight * 0.22,
      selectionLayout.rowHeight,
      1080
    );
    const selectionTop = clamp(
      Math.max(0, (selectionLayout.anchors[0]?.stageY || 0) - selectionLayout.rowHeight * 0.18),
      0,
      1080
    );
    selectionLayout.columns.forEach((column) => {
      const extraWidth =
        selectionLayout.mode === 'single-check' ? column.width * 0.45 : column.width * 0.12;
      const rect = {
        x: clamp(column.left - extraWidth * 0.35, 0, 1920),
        y: selectionTop,
        width: Math.min(1920, column.width + extraWidth),
        height: columnHeight,
      };
      const bgColor = samplePdfCanvasBackgroundColor(outputCanvas, rect);
      paintPdfCleanupRect(outputContext, rect, bgColor);
    });
  }

  const dragPoolRect = getPdfDragPoolRect(stagePage);
  if (dragPoolRect) {
    const bgColor = samplePdfCanvasBackgroundColor(outputCanvas, dragPoolRect);
    paintPdfCleanupRect(outputContext, dragPoolRect, bgColor);
  }

  const answerLine = stageLines.find((line) =>
    normalizePdfText(line.text).includes('dogru eslestirme')
  );
  if (answerLine) {
    const answerY = Number(answerLine.y || 0);
    const nearbyAnswerLines = stageLines.filter((line) => {
      const ly = Number(line.y || 0);
      return ly >= answerY && ly <= answerY + 120;
    });
    const answerRect = getPdfStageRectForLines(
      nearbyAnswerLines.length ? nearbyAnswerLines : [answerLine],
      1920,
      1080,
      24,
      18
    );
    const bgColor = samplePdfCanvasBackgroundColor(outputCanvas, answerRect);
    paintPdfCleanupRect(outputContext, answerRect, bgColor);
  }

  const bottomRightRedNote = detectRedAnnotationBounds(outputCanvas, {
    x: outputCanvas.width * 0.58,
    y: outputCanvas.height * 0.72,
    width: outputCanvas.width * 0.32,
    height: outputCanvas.height * 0.22,
  });
  if (bottomRightRedNote) {
    const bgColor = samplePdfCanvasBackgroundColor(outputCanvas, bottomRightRedNote);
    paintPdfCleanupRect(outputContext, bottomRightRedNote, bgColor);
  }

  const bottomLeftRedNote = detectRedAnnotationBounds(outputCanvas, {
    x: outputCanvas.width * 0.02,
    y: outputCanvas.height * 0.74,
    width: outputCanvas.width * 0.62,
    height: outputCanvas.height * 0.22,
  });
  if (bottomLeftRedNote) {
    const bgColor = samplePdfCanvasBackgroundColor(outputCanvas, bottomLeftRedNote);
    paintPdfCleanupRect(outputContext, bottomLeftRedNote, bgColor);
  }

  const blob = await new Promise((resolve) => outputCanvas.toBlob(resolve, 'image/png', 0.92));
  if (!blob) throw new Error('PDF sayfasi gorsellestirilemedi.');
  const safeBase = (fileName || 'pdf').replace(/\.[^.]+$/g, '').replace(/[^\w-]+/g, '-');
  const uploadFile = new File([blob], `${safeBase}-sayfa-${pageIndex + 1}.png`, {
    type: 'image/png',
  });
  const url = await uploadMediaFile(uploadFile);
  return {
    url,
    width: 1920,
    height: 1080,
    transform,
    lines: stageLines,
    layoutHints,
  };
}

// eslint-disable-next-line no-unused-vars -- Legacy PDF import pipeline kept dormant while PdfCleanStudio owns imports.
async function analyzePdfFile(file, onProgress = () => {}) {
  const pdfjsLib = await ensurePdfJsLib();
  const data = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data }).promise;
  const pages = [];

  for (let pageIndex = 0; pageIndex < pdf.numPages; pageIndex += 1) {
    onProgress(`PDF okunuyor: sayfa ${pageIndex + 1}/${pdf.numPages}`, 'info');
    const page = await pdf.getPage(pageIndex + 1);
    const textContent = await page.getTextContent();
    const rawLines = buildPdfTextLines(textContent.items || [], page.getViewport({ scale: 1 }));
    const marker = detectPdfMarker(rawLines);
    onProgress(`Sayfa ${pageIndex + 1}: gorsel hazirlaniyor...`, 'info');
    const asset = await renderPdfPageAsset(page, file.name, pageIndex, rawLines, onProgress);
    const lines = asset.lines || mapPdfLinesToStage(rawLines, asset.transform);
    pages.push({
      pageNumber: pageIndex + 1,
      lines,
      marker,
      text: lines.map((line) => line.text).join('\n'),
      imageUrl: asset.url,
      width: asset.width,
      height: asset.height,
      layoutHints: asset.layoutHints || null,
    });
  }

  const groups = [];
  let currentGroup = null;
  pages.forEach((page, index) => {
    const pageMarker = page.marker;
    const fallbackKey = `sayfa-${index + 1}`;
    if (!currentGroup) {
      currentGroup = {
        id: uid(),
        markerKey: pageMarker?.key || fallbackKey,
        markerLabel: pageMarker?.label || `Etkinlik ${index + 1}`,
        markerIndex: pageMarker?.index || index + 1,
        pages: [],
      };
      groups.push(currentGroup);
    } else if (pageMarker && pageMarker.key !== currentGroup.markerKey) {
      currentGroup = {
        id: uid(),
        markerKey: pageMarker.key,
        markerLabel: pageMarker.label,
        markerIndex: pageMarker.index || groups.length + 1,
        pages: [],
      };
      groups.push(currentGroup);
    }
    currentGroup.pages.push(page);
  });

  const markerCount = pages.filter((page) => !!page.marker).length;
  if ((markerCount === 0 || groups.length === 1) && pages.length > 1) {
    const fallbackGroups = buildFallbackPdfGroups(pages);
    if (fallbackGroups.length > groups.length) {
      groups.length = 0;
      fallbackGroups.forEach((group) => groups.push(group));
    }
  }

  onProgress('Storyboard yapisi cikariliyor...', 'info');
  const storyboard = buildStoryboardConfig({ document: file.name, pages });
  const storyboardPageMap = new Map(
    (storyboard?.pages || []).map((page) => [Number(page?.pageNumber || 0), page])
  );

  const items = await Promise.all(
    groups.map(async (group, index) => {
      const allLines = group.pages.flatMap((page) => page.lines);
      const title = inferPdfDraftTitle(allLines, group.markerLabel || `PDF Etkinlik ${index + 1}`);
      const lastPage = group.pages[group.pages.length - 1] || {};
      const storyboardPages = group.pages
        .map((page) => storyboardPageMap.get(Number(page?.pageNumber || 0)))
        .filter(Boolean);
      const primaryInteractionType = pickPrimaryStoryboardInteraction(storyboardPages);
      const { draggableTerms: storyboardDragTerms, answerTerms: storyboardAnswerTerms } =
        extractStoryboardTermLists(storyboardPages);
      const draggableTerms = mergePdfTermLists(
        extractPdfDragTerms(lastPage?.lines || []),
        lastPage?.layoutHints?.draggableTerms || [],
        storyboardDragTerms
      );
      const answerTerms = mergePdfTermLists(
        extractPdfAnswerTerms(lastPage?.lines || []),
        lastPage?.layoutHints?.answerTerms || [],
        storyboardAnswerTerms
      );
      const layoutKind =
        group.pages
          .map((page) => page?.layoutHints?.kindHint)
          .find((value) => value && value !== 'unknown') || null;
      const detectedKind =
        layoutKind ||
        detectPdfDraftKind(allLines, group.pages.length, group.pages[0]?.marker || null);
      const storyboardKind = mapStoryboardInteractionTypeToDraftKind(primaryInteractionType);
      let kind = storyboardKind || detectedKind;
      const status = detectPdfDraftStatus(kind, { draggableTerms, answerTerms });
      const instruction = sanitizePdfText(
        storyboardPages.map((page) => page?.instruction).find(Boolean) || ''
      );
      let developerNote = sanitizePdfText(
        storyboardPages
          .map((page) => page?.developerNote)
          .filter(Boolean)
          .join(' ')
      );
      const extractedItemCount = countStoryboardExtractedItems(storyboardPages);

      // Offline AI Analysis
      try {
        const textSample = allLines
          .slice(0, 20)
          .map((l) => l.text)
          .join(' ');
        if (textSample.trim().length > 10) {
          onProgress(
            `Etkinlik ${index + 1} için çevrimdışı yapay zeka analizi yapılıyor...`,
            'info'
          );
          const aiResult = await analyzeTextOffline(
            textSample,
            'Bu sayfanın etkinlik türünü ve içindeki soruları özetle.'
          );
          if (aiResult && aiResult.analysis) {
            developerNote = [developerNote, `[AI Analizi]: ${aiResult.analysis}`]
              .filter(Boolean)
              .join('\n\n');
            if (kind === 'unknown' || kind === 'reading') {
              const lowerAnalysis = aiResult.analysis.toLowerCase();
              if (
                lowerAnalysis.includes('sürükle bırak') ||
                lowerAnalysis.includes('drag and drop')
              )
                kind = 'drag-drop';
              else if (
                lowerAnalysis.includes('çoktan seçmeli') ||
                lowerAnalysis.includes('multiple choice')
              )
                kind = 'selection';
              else if (
                lowerAnalysis.includes('doğru yanlış') ||
                lowerAnalysis.includes('true or false')
              )
                kind = 'selection';
              else if (
                lowerAnalysis.includes('boşluk doldurma') ||
                lowerAnalysis.includes('fill in the blanks')
              )
                kind = 'drag-drop';
            }
          }
        }
      } catch (err) {
        // AI analysis silently failed
      }

      return {
        id: group.id,
        order: index + 1,
        markerKey: group.markerKey,
        markerLabel: group.markerLabel || `Etkinlik ${index + 1}`,
        name: title,
        kind,
        status,
        pageCount: group.pages.length,
        startPage: group.pages[0]?.pageNumber || 1,
        endPage: group.pages[group.pages.length - 1]?.pageNumber || 1,
        draggableTerms,
        answerTerms,
        pages: group.pages,
        prompt:
          instruction ||
          allLines
            .slice(0, 8)
            .map((line) => line.text)
            .join(' '),
        interactionType: primaryInteractionType,
        instruction,
        developerNote,
        extractedItemCount,
        storyboardPages,
      };
    })
  );

  return {
    fileName: file.name,
    pageCount: pdf.numPages,
    items,
    storyboard,
  };
}


function getMedian(values = []) {
  if (!values.length) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0 ? (sorted[middle - 1] + sorted[middle]) / 2 : sorted[middle];
}




function safeClone(value, fallback = {}) {
  try {
    return JSON.parse(JSON.stringify(value ?? fallback));
  } catch {
    return fallback;
  }
}

function getFitScale(stageWidth, stageHeight, maxWidth, maxHeight) {
  const safeWidth = Math.max(320, maxWidth || 0);
  const safeHeight = Math.max(240, maxHeight || 0);
  const sw = Math.max(1, stageWidth || 1);
  const sh = Math.max(1, stageHeight || 1);
  return Math.max(0.1, Math.min(safeWidth / sw, safeHeight / sh));
}



function createObjectFromActivity(activity = {}, type = 'text') {
  const object = createObject(type);
  if (type !== 'draggable' && type !== 'dropzone') return object;
  const family = getActivityDragDropDefaults(activity)[type];
  return {
    ...object,
    width: family.width,
    height: family.height,
    style: { ...family.style },
  };
}

function updateActivityObject(activity = {}, objectId = '', patch = {}, options = {}) {
  const objects = Array.isArray(activity?.objects) ? activity.objects : [];
  const target = objects.find((item) => item.id === objectId);
  if (!target) return activity;

  const shouldSyncFamily =
    !!options.syncDragDropFamily && (target.type === 'draggable' || target.type === 'dropzone');
  let nextActivity = activity;

  if (shouldSyncFamily) {
    const familyDefaults = getActivityDragDropDefaults(activity)[target.type];
    const familyPatch = {};

    if (Object.prototype.hasOwnProperty.call(patch, 'width')) {
      familyPatch.width = Math.max(20, Number(patch.width) || familyDefaults.width);
    }
    if (Object.prototype.hasOwnProperty.call(patch, 'height')) {
      familyPatch.height = Math.max(20, Number(patch.height) || familyDefaults.height);
    }
    if (patch.style) {
      familyPatch.style = upgradeDragDropStyle(target.type, {
        ...familyDefaults.style,
        ...patch.style,
      });
    }

    if (Object.keys(familyPatch).length) {
      const nextDefaults = {
        ...familyDefaults,
        ...familyPatch,
        style: familyPatch.style ? { ...familyPatch.style } : familyDefaults.style,
      };
      nextActivity = {
        ...activity,
        dragDropDefaults: {
          ...getActivityDragDropDefaults(activity),
          [target.type]: nextDefaults,
        },
        objects: objects.map((item) =>
          item.type === target.type
            ? {
                ...item,
                ...(Object.prototype.hasOwnProperty.call(familyPatch, 'width')
                  ? { width: nextDefaults.width }
                  : {}),
                ...(Object.prototype.hasOwnProperty.call(familyPatch, 'height')
                  ? { height: nextDefaults.height }
                  : {}),
                ...(familyPatch.style ? { style: { ...nextDefaults.style } } : {}),
              }
            : item
        ),
      };
    }
  }

  const objectPatch = { ...patch };
  if (shouldSyncFamily) {
    delete objectPatch.width;
    delete objectPatch.height;
    delete objectPatch.style;
  }

  if (!Object.keys(objectPatch).length) return nextActivity;

  return {
    ...nextActivity,
    objects: (nextActivity.objects || []).map((item) => {
      if (item.id !== objectId) return item;
      const nextItem = { ...item, ...objectPatch };
      if (!options.preserveGeneratedBy && isGeneratedAnswerTemplateObject(item)) {
        delete nextItem.generatedBy;
        nextItem.userEditedTemplate = true;
      }
      if (!options.preserveGeneratedBy && isGeneratedSceneTemplateObject(item)) {
        nextItem.userEditedSceneTemplate = true;
      }
      return nextItem;
    }),
  };
}

function getObjectSelectionBounds(items = []) {
  if (!items.length) return null;
  const left = Math.min(...items.map((item) => Number(item.x) || 0));
  const top = Math.min(...items.map((item) => Number(item.y) || 0));
  const right = Math.max(...items.map((item) => (Number(item.x) || 0) + (Number(item.width) || 0)));
  const bottom = Math.max(
    ...items.map((item) => (Number(item.y) || 0) + (Number(item.height) || 0))
  );
  return {
    left,
    top,
    right,
    bottom,
    width: right - left,
    height: bottom - top,
  };
}

function alignActivitySelection(activity = {}, selectedIds = new Set(), mode = 'left') {
  const ids = selectedIds instanceof Set ? selectedIds : new Set(selectedIds || []);
  if (ids.size < 2) return activity;
  const objects = Array.isArray(activity.objects) ? activity.objects : [];
  const selectedObjects = objects.filter((item) => ids.has(item.id));
  const bounds = getObjectSelectionBounds(selectedObjects);
  if (!bounds) return activity;

  return {
    ...activity,
    objects: objects.map((item) => {
      if (!ids.has(item.id)) return item;
      if (mode === 'left') return { ...item, x: bounds.left };
      if (mode === 'center') return { ...item, x: bounds.left + (bounds.width - item.width) / 2 };
      if (mode === 'right') return { ...item, x: bounds.right - item.width };
      if (mode === 'top') return { ...item, y: bounds.top };
      if (mode === 'middle') return { ...item, y: bounds.top + (bounds.height - item.height) / 2 };
      if (mode === 'bottom') return { ...item, y: bounds.bottom - item.height };
      return item;
    }),
  };
}

function distributeActivitySelection(activity = {}, selectedIds = new Set(), axis = 'horizontal') {
  const ids = selectedIds instanceof Set ? selectedIds : new Set(selectedIds || []);
  if (ids.size < 3) return activity;
  const objects = Array.isArray(activity.objects) ? activity.objects : [];
  const selectedObjects = objects.filter((item) => ids.has(item.id));
  if (selectedObjects.length < 3) return activity;

  const isHorizontal = axis === 'horizontal';
  const ordered = [...selectedObjects].sort((left, right) =>
    isHorizontal
      ? left.x - right.x || left.zIndex - right.zIndex
      : left.y - right.y || left.zIndex - right.zIndex
  );
  const start = isHorizontal ? ordered[0].x : ordered[0].y;
  const end = isHorizontal
    ? ordered[ordered.length - 1].x + ordered[ordered.length - 1].width
    : ordered[ordered.length - 1].y + ordered[ordered.length - 1].height;
  const totalSize = ordered.reduce(
    (sum, item) => sum + (isHorizontal ? item.width : item.height),
    0
  );
  const gap = (end - start - totalSize) / Math.max(1, ordered.length - 1);
  let cursor = start;
  const positionMap = new Map();

  ordered.forEach((item) => {
    positionMap.set(item.id, cursor);
    cursor += (isHorizontal ? item.width : item.height) + gap;
  });

  return {
    ...activity,
    objects: objects.map((item) => {
      if (!positionMap.has(item.id)) return item;
      return isHorizontal
        ? { ...item, x: positionMap.get(item.id) }
        : { ...item, y: positionMap.get(item.id) };
    }),
  };
}

function getAnswerPlacementFrames(activity = {}) {
  if (!activity || (activity.type !== 'drag-drop' && activity.type !== 'mixed')) return {};
  const canvasObjects = Array.isArray(activity.objects) ? activity.objects : [];
  const dragById = Object.fromEntries(
    canvasObjects.filter((item) => item.type === 'draggable').map((item) => [item.id, item])
  );
  const dropById = Object.fromEntries(
    canvasObjects.filter((item) => item.type === 'dropzone').map((item) => [item.id, item])
  );
  const pairs = getDragDropPairsFromMatches(getCorrectDragMatches(activity));
  const layout = getDragDropSettings(activity).answerPlacementLayout || 'stack';
  const dropStackById = {};
  const stageW = Number(activity.stageWidth) || 1920;
  const stageH = Number(activity.stageHeight) || 1080;
  const frames = {};

  pairs.forEach((pair) => {
    const drag = dragById[pair.dragId];
    const drop = dropById[pair.dropId];
    if (!drag || !drop) return;

    const dragWidth = Number(drag.width) || 1;
    const dragHeight = Number(drag.height) || 1;
    const dropWidth = Number(drop.width) || dragWidth;
    const dropHeight = Number(drop.height) || dragHeight;
    const stackIndex = dropStackById[drop.id] || 0;
    dropStackById[drop.id] = stackIndex + 1;
    const gap = 8;
    const rowCount = Math.max(1, Math.floor((dropWidth + gap) / Math.max(1, dragWidth + gap)));
    const gridRow = Math.floor(stackIndex / rowCount);
    const gridCol = stackIndex % rowCount;

    let targetX = Math.round((Number(drop.x) || 0) + (dropWidth - dragWidth) / 2);
    let targetY = Math.round((Number(drop.y) || 0) + (dropHeight - dragHeight) / 2);
    if (layout === 'row') {
      targetX = Math.round((Number(drop.x) || 0) + 4 + stackIndex * (dragWidth + gap));
      targetY = Math.round((Number(drop.y) || 0) + (dropHeight - dragHeight) / 2);
    }
    if (layout === 'grid') {
      targetX = Math.round((Number(drop.x) || 0) + 4 + gridCol * (dragWidth + gap));
      targetY = Math.round((Number(drop.y) || 0) + 4 + gridRow * (dragHeight + gap));
    }

    frames[getDragDropPairKey(pair.dragId, pair.dropId)] = {
      x: clamp(targetX, 0, Math.max(0, stageW - dragWidth)),
      y: clamp(targetY, 0, Math.max(0, stageH - dragHeight)),
      width: dragWidth,
      height: dragHeight,
      drag,
      drop,
    };
  });

  return frames;
}

function syncAnswerPlacementObjects(activity = {}) {
  const objects = Array.isArray(activity.objects) ? activity.objects : [];
  if (!objects.some((item) => item.generatedBy === 'answer-placement')) return activity;
  const frames = getAnswerPlacementFrames(activity);
  const frameEntries = Object.entries(frames);
  const usedFrameKeys = new Set();

  return {
    ...activity,
    objects: objects.map((item) => {
      if (item.generatedBy !== 'answer-placement') return item;
      const baseItem = {
        ...item,
        answerStatic: true,
        disableDrag: false,
        locked: false,
      };
      if (!frameEntries.length) return baseItem;
      let pairKey =
        item.answerPairKey ||
        getDragDropPairKey(
          item.sourceDragId || item.dragId || '',
          item.targetDropId || item.dropId || ''
        );
      let frame = frames[pairKey];
      if (!frame) {
        const legacyMatch = frameEntries.find(
          ([key, entry]) =>
            !usedFrameKeys.has(key) &&
            (entry.drag.id === item.sourceDragId ||
              (String(entry.drag.label || '').trim() &&
                String(entry.drag.label || '').trim() === String(item.label || '').trim()))
        );
        if (legacyMatch) {
          pairKey = legacyMatch[0];
          frame = legacyMatch[1];
        }
      }
      if (!frame) return baseItem;
      usedFrameKeys.add(pairKey);
      const manualPlacement = item.answerPlacementManual === true;
      return {
        ...baseItem,
        x: manualPlacement ? item.x : frame.x,
        y: manualPlacement ? item.y : frame.y,
        width: manualPlacement ? item.width : frame.width,
        height: manualPlacement ? item.height : frame.height,
        sourceDragId: item.sourceDragId || frame.drag.id,
        targetDropId: item.targetDropId || frame.drop.id,
        answerPairKey: pairKey,
      };
    }),
  };
}



function createTriggerItem(index = 0) {
  return {
    id: uid(),
    when: 'onClick',
    target: 'Secili Nesne',
    action: 'SayfaGec',
    value: '__next__',
    extra: '',
    stateKey: 'visited',
    stateValue: 'true',
    name: `Tetik ${index + 1}`,
    conditionMode: 'all',
    conditions: [],
  };
}

function createTriggerConditionItem(index = 0) {
  return {
    id: uid(),
    sourceType: 'variable',
    sourceId: '',
    stateKey: 'visited',
    operator: 'eq',
    value: '',
    name: `Kosul ${index + 1}`,
  };
}


function getVariableTypeLabel(type = 'text') {
  return VARIABLE_TYPES.find((item) => item.value === type)?.label || type;
}

function formatVariableValue(value, type = 'text') {
  if (type === 'boolean') return value ? 'True' : 'False';
  if (type === 'number') return Number.isFinite(Number(value)) ? String(Number(value)) : '0';
  return String(value ?? '');
}

function resolveColorPickerValue(value, fallback = '#111111') {
  const match = String(value || '').match(/#[0-9a-fA-F]{6}/);
  return match ? match[0] : fallback;
}

function buildVariableUsageCountMap(activities = []) {
  return (activities || []).reduce((counts, activity) => {
    getActivitySlides(activity).forEach((slide) => {
      (slide.triggers || []).forEach((trigger) => {
        if (
          ['DegiskenAta', 'DegiskenArttir', 'DegiskenAzalt'].includes(trigger?.action) &&
          trigger?.value
        ) {
          counts[trigger.value] = (counts[trigger.value] || 0) + 1;
        }
        (trigger?.conditions || []).forEach((condition) => {
          if (condition?.sourceType === 'variable' && condition?.sourceId) {
            counts[condition.sourceId] = (counts[condition.sourceId] || 0) + 1;
          }
        });
      });
    });
    return counts;
  }, {});
}

function buildBuiltInVariableRows({ activity = {}, projectName = '', bookName = '' } = {}) {
  const slides = getActivitySlides(activity);
  const currentSlideIndex =
    Math.max(
      0,
      slides.findIndex((slide) => slide.id === activity?.currentSlideId)
    ) + 1;
  return [
    {
      id: 'builtin.project',
      name: 'Project.Title',
      type: 'text',
      value: projectName || 'Untitled Project',
      useCount: 0,
    },
    {
      id: 'builtin.book',
      name: 'Book.Title',
      type: 'text',
      value: bookName || 'Untitled Book',
      useCount: 0,
    },
    {
      id: 'builtin.activity',
      name: 'Activity.Name',
      type: 'text',
      value: activity?.name || 'Untitled Activity',
      useCount: 0,
    },
    {
      id: 'builtin.scene',
      name: 'Scene.Name',
      type: 'text',
      value: activity?.sceneName || 'Untitled Scene',
      useCount: 0,
    },
    {
      id: 'builtin.slideIndex',
      name: 'Slide.Index',
      type: 'number',
      value: currentSlideIndex,
      useCount: 0,
    },
    {
      id: 'builtin.slideCount',
      name: 'Slide.Count',
      type: 'number',
      value: slides.length,
      useCount: 0,
    },
    {
      id: 'builtin.layerCount',
      name: 'Layer.Count',
      type: 'number',
      value: getActivityLayers(activity).length,
      useCount: 0,
    },
    {
      id: 'builtin.objectCount',
      name: 'Object.Count',
      type: 'number',
      value: Array.isArray(activity?.objects) ? activity.objects.length : 0,
      useCount: 0,
    },
  ];
}



const AUTO_LAYER_NAME_PRESETS = ['menu', 'explanation', 'normal', 'Correct', 'Incorrect', 'cevap'];


function normalizeSlideObjectsForLayers(objects = [], layers = []) {
  const layerIds = new Set((layers || []).map((layer) => layer.id).filter(Boolean));
  return (objects || []).map((object, index) => {
    const width = Math.max(1, Number(object.width ?? 1) || 1);
    const height = Math.max(1, Number(object.height ?? 1) || 1);
    const x = Number.isFinite(Number(object.x)) ? Number(object.x) : 0;
    const y = Number.isFinite(Number(object.y)) ? Number(object.y) : 0;
    const layerId = layerIds.has(object.layerId) ? object.layerId : 'base';
    return {
      ...object,
      id: object.id || uid(),
      x,
      y,
      width,
      height,
      zIndex: Number.isFinite(Number(object.zIndex)) ? Number(object.zIndex) : index + 1,
      layerId,
      visible: object.visible !== false,
      locked: !!object.locked,
    };
  });
}

function normalizeSlideTriggersForScene(triggers = [], objects = [], layers = []) {
  const objectIds = new Set((objects || []).map((object) => object.id).filter(Boolean));
  const layerIds = new Set((layers || []).map((layer) => layer.id).filter(Boolean));
  const staticSources = new Set([
    'Secili Nesne',
    'TiklananNesne',
    'selected',
    '__activity__',
    'Sahne',
  ]);
  const validWhens = new Set([
    'onClick',
    'onHover',
    'onDrop',
    'onDragEnter',
    'onDragLeave',
    'onKeypress',
    'onDoubleClick',
    'onLoad',
    'onOffSlide',
    'onTimer',
    'onTimelineEnd',
    'onMediaEnd',
    'onMediaStart',
    'onStateChange',
    'onVariableChange',
    'onDropCorrect',
    'onDropIncorrect',
    'onSubmit',
  ]);

  return (Array.isArray(triggers) ? triggers : []).map((trigger, indexValue) => {
    trigger = trigger && typeof trigger === 'object' ? trigger : {};
    const when = validWhens.has(trigger.when) ? trigger.when : 'onClick';
    const action = trigger.action || 'SayfaGec';
    let target = when === 'onLoad' ? '__activity__' : trigger.target || 'Secili Nesne';
    let value = trigger.value ?? '';

    if (!staticSources.has(target) && !objectIds.has(target)) {
      target = when === 'onLoad' ? '__activity__' : 'Secili Nesne';
    }

    if (action === 'KatmanaGec' && !layerIds.has(value)) {
      value = layerIds.has('base') ? 'base' : layers[0]?.id || '';
    }

    if (
      (action === 'Goster' || action === 'Gizle' || action === 'NesneDurumuAyarla') &&
      !objectIds.has(value)
    ) {
      value = '';
    }

    if ((action === 'SayfaGec' || action === 'SliderGec') && !value) {
      value = '__next__';
    }

    return {
      ...createTriggerItem(indexValue),
      ...trigger,
      when,
      target,
      action,
      value,
      conditions: Array.isArray(trigger.conditions)
        ? trigger.conditions.map((condition, conditionIndex) => ({
            ...createTriggerConditionItem(conditionIndex),
            ...(condition && typeof condition === 'object' ? condition : {}),
          }))
        : [],
    };
  });
}

// eslint-disable-next-line no-unused-vars -- Legacy PDF import object factory retained for dormant import flow.
