                      x: d.x,
                      y: d.y,
                      width: d.width,
                      height: d.height,
                      rotation: 0,
                      label: d.label,
                      locked: false,
                      visible: true,
                      zIndex: 1,
                      imageData: null,
                      mediaUrl: '',
                      mediaName: '',
                      group: '',
                      scope: '',
